-- Historical reference settlement has no business source/event foreign keys.
CREATE TABLE migration_open_items(
 id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES migration_projects(id),cutover_id TEXT NOT NULL REFERENCES migration_cutovers(id),record_id TEXT NOT NULL REFERENCES migration_records(id),
 ledger_id TEXT NOT NULL,book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,source_system_key TEXT NOT NULL,external_book_id TEXT NOT NULL,external_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('receivable','payable')),source_account_code TEXT NOT NULL,target_account_code TEXT NOT NULL,counterparty_code TEXT NOT NULL,
 counterparty_id TEXT NOT NULL REFERENCES company_master_entities(id),amount_cents INTEGER NOT NULL CHECK(typeof(amount_cents)='integer' AND amount_cents>0 AND amount_cents<=99999999999999),
 occurred_on TEXT NOT NULL,due_on TEXT,master_bindings_json TEXT NOT NULL CHECK(json_type(master_bindings_json)='array'),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,
 UNIQUE(project_id,external_id),UNIQUE(firm_id,ledger_id,source_system_key,external_book_id,external_id),UNIQUE(id,project_id,firm_id,company_id),FOREIGN KEY(project_id,firm_id,company_id) REFERENCES migration_projects(id,firm_id,company_id),FOREIGN KEY(book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id)
);
CREATE TABLE migration_clearance_previews(
 id TEXT PRIMARY KEY,project_id TEXT NOT NULL,book_id TEXT NOT NULL,bank_book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),
 request_json TEXT NOT NULL CHECK(json_type(request_json)='object'),plan_json TEXT NOT NULL CHECK(json_type(plan_json)='object'),fingerprint TEXT NOT NULL CHECK(length(fingerprint)=64),created_at TEXT NOT NULL,expires_at TEXT NOT NULL,
 UNIQUE(id,project_id,firm_id,company_id),FOREIGN KEY(project_id,firm_id,company_id) REFERENCES migration_projects(id,firm_id,company_id),FOREIGN KEY(bank_book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id)
);
CREATE TABLE migration_clearance_commands(
 id TEXT PRIMARY KEY,project_id TEXT NOT NULL,book_id TEXT NOT NULL,bank_book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,preview_id TEXT NOT NULL UNIQUE,
 bank_source_id TEXT NOT NULL,bank_draft_id TEXT NOT NULL,bank_account_code TEXT NOT NULL,expected_draft_version INTEGER NOT NULL CHECK(expected_draft_version>0),applied_draft_version INTEGER NOT NULL CHECK(applied_draft_version=expected_draft_version+1),
 previous_draft_json TEXT NOT NULL CHECK(json_type(previous_draft_json)='object'),plan_json TEXT NOT NULL CHECK(json_type(plan_json)='object'),created_by TEXT NOT NULL REFERENCES users(id),idempotency_key TEXT NOT NULL CHECK(length(idempotency_key) BETWEEN 8 AND 120),request_fingerprint TEXT NOT NULL CHECK(length(request_fingerprint)=64),created_at TEXT NOT NULL,
 UNIQUE(firm_id,created_by,idempotency_key),UNIQUE(id,project_id,firm_id,company_id),FOREIGN KEY(project_id,firm_id,company_id) REFERENCES migration_projects(id,firm_id,company_id),FOREIGN KEY(preview_id,project_id,firm_id,company_id) REFERENCES migration_clearance_previews(id,project_id,firm_id,company_id),FOREIGN KEY(bank_source_id,bank_book_id) REFERENCES sources(id,book_id),FOREIGN KEY(bank_draft_id,bank_book_id) REFERENCES drafts(id,book_id)
);
CREATE TABLE migration_clearance_allocations(
 id TEXT PRIMARY KEY,command_id TEXT NOT NULL,project_id TEXT NOT NULL,bank_book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,item_id TEXT NOT NULL,
 bank_source_id TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(typeof(amount_cents)='integer' AND amount_cents>0 AND amount_cents<=99999999999999),target_account_code TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,
 UNIQUE(command_id,item_id),FOREIGN KEY(command_id,project_id,firm_id,company_id) REFERENCES migration_clearance_commands(id,project_id,firm_id,company_id),FOREIGN KEY(item_id,project_id,firm_id,company_id) REFERENCES migration_open_items(id,project_id,firm_id,company_id),FOREIGN KEY(bank_source_id,bank_book_id) REFERENCES sources(id,book_id)
);
CREATE TABLE migration_clearance_reversals(
 id TEXT PRIMARY KEY,command_id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL,bank_book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,
 idempotency_key TEXT NOT NULL CHECK(length(idempotency_key) BETWEEN 8 AND 120),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),expected_fingerprint TEXT NOT NULL CHECK(length(expected_fingerprint)=64),UNIQUE(firm_id,created_by,idempotency_key),
 FOREIGN KEY(command_id,project_id,firm_id,company_id) REFERENCES migration_clearance_commands(id,project_id,firm_id,company_id)
);
CREATE INDEX migration_open_items_page ON migration_open_items(project_id,occurred_on,external_id,id);
CREATE INDEX migration_clearance_item_balance ON migration_clearance_allocations(item_id,command_id);
CREATE INDEX migration_clearance_bank_balance ON migration_clearance_allocations(bank_source_id,command_id);
CREATE INDEX migration_clearance_commands_page ON migration_clearance_commands(project_id,created_at DESC,id);

CREATE TRIGGER migration_open_item_proof BEFORE INSERT ON migration_open_items BEGIN
 SELECT CASE WHEN NOT EXISTS(
  SELECT 1 FROM migration_projects p JOIN migration_cutovers c ON c.project_id=p.id JOIN migration_validations v ON v.id=c.validation_id JOIN migration_records r ON r.id=NEW.record_id
  JOIN company_master_entities e ON e.id=NEW.counterparty_id AND e.firm_id=p.firm_id AND e.company_id=p.company_id AND e.kind='counterparty' AND e.active=1
  WHERE p.id=NEW.project_id AND p.status='active' AND c.id=NEW.cutover_id AND p.book_id=NEW.book_id AND p.ledger_id=NEW.ledger_id AND r.project_id=p.id AND r.kind='open_item' AND r.external_id=NEW.external_id
  AND p.source_system_key=NEW.source_system_key AND p.external_book_id=NEW.external_book_id
  AND json_extract(v.report_json,'$.coverage.open_item_reconciliation_complete')=1
  AND json_extract(r.payload_json,'$.kind')=NEW.kind AND json_extract(r.payload_json,'$.counterparty_code')=NEW.counterparty_code
  AND json_extract(r.payload_json,'$.remaining_amount')=printf('%d.%02d',NEW.amount_cents/100,NEW.amount_cents%100)
  AND json_extract(r.payload_json,'$.occurred_on')=NEW.occurred_on AND json_extract(r.payload_json,'$.due_on') IS NEW.due_on
  AND json(NEW.master_bindings_json)=json(json_extract(c.payload_json,'$.master_bindings'))
  AND EXISTS(SELECT 1 FROM json_each(v.report_json,'$.open_item_bindings') b WHERE json_extract(b.value,'$.external_id')=NEW.external_id AND json_extract(b.value,'$.account_code')=NEW.source_account_code AND json_extract(b.value,'$.counterparty_code')=NEW.counterparty_code)
  AND EXISTS(SELECT 1 FROM json_each(c.payload_json,'$.master_bindings') b WHERE json_extract(b.value,'$.kind')='counterparty' AND json_extract(b.value,'$.source_code')=NEW.counterparty_code AND json_extract(b.value,'$.target_id')=NEW.counterparty_id)
  AND EXISTS(SELECT 1 FROM migration_mapping_versions m,json_each(m.payload_json,'$.accounts') a WHERE m.project_id=p.id AND m.version=(SELECT max(version) FROM migration_mapping_versions WHERE project_id=p.id) AND json_extract(a.value,'$.source_code')=NEW.source_account_code AND json_extract(a.value,'$.target_code')=NEW.target_account_code)
 ) THEN RAISE(ABORT,'Historical open item requires verified cutover evidence and bindings') END;
END;
CREATE TRIGGER migration_clearance_preview_scope BEFORE INSERT ON migration_clearance_previews BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM migration_projects p JOIN ledger_periods l ON l.ledger_id=p.ledger_id AND l.book_id=NEW.bank_book_id JOIN periods q ON q.book_id=l.book_id JOIN users u ON u.id=NEW.created_by AND u.active=1 WHERE p.id=NEW.project_id AND p.status='active' AND p.book_id=NEW.book_id AND p.firm_id=NEW.firm_id AND p.company_id=NEW.company_id AND q.status='open') THEN RAISE(ABORT,'Clearance requires active historical scope and current open ledger period') END;
END;
CREATE TRIGGER migration_clearance_command_proof BEFORE INSERT ON migration_clearance_commands BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM migration_clearance_previews p JOIN sources s ON s.id=NEW.bank_source_id AND s.book_id=NEW.bank_book_id JOIN drafts d ON d.id=NEW.bank_draft_id AND d.source_id=s.id JOIN periods q ON q.book_id=s.book_id WHERE p.id=NEW.preview_id AND p.project_id=NEW.project_id AND p.created_by=NEW.created_by AND p.plan_json=NEW.plan_json AND d.status='draft' AND d.version=NEW.expected_draft_version AND q.status='open' AND s.source_kind='bank' AND s.fingerprint=json_extract(NEW.plan_json,'$.bank_fingerprint') AND s.amount_cents=json_extract(NEW.plan_json,'$.total_cents') AND s.direction=json_extract(NEW.plan_json,'$.direction'))
 OR EXISTS(SELECT 1 FROM migration_clearance_allocations a WHERE a.bank_source_id=NEW.bank_source_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=a.command_id))
 OR EXISTS(SELECT 1 FROM ai_bank_links WHERE bank_source_id=NEW.bank_source_id)
 OR EXISTS(SELECT 1 FROM settlement_allocations a WHERE a.bank_source_id=NEW.bank_source_id AND NOT EXISTS(SELECT 1 FROM settlement_reversals r WHERE r.allocation_id=a.id))
 OR (SELECT sum(json_extract(x.value,'$.amount_cents')) FROM json_each(NEW.plan_json,'$.parts') x)<>(SELECT amount_cents FROM sources WHERE id=NEW.bank_source_id)
 OR (SELECT count(DISTINCT json_extract(x.value,'$.item_id')) FROM json_each(NEW.plan_json,'$.parts') x)<>(SELECT count(*) FROM json_each(NEW.plan_json,'$.parts'))
 THEN RAISE(ABORT,'Historical clearance command requires frozen unused current bank draft') END;
END;
CREATE TRIGGER migration_clearance_allocation_proof BEFORE INSERT ON migration_clearance_allocations BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM migration_clearance_commands c JOIN migration_open_items i ON i.id=NEW.item_id JOIN drafts d ON d.id=c.bank_draft_id JOIN company_master_entities e ON e.id=i.counterparty_id AND e.active=1 WHERE c.id=NEW.command_id AND c.project_id=NEW.project_id AND c.bank_book_id=NEW.bank_book_id AND c.bank_source_id=NEW.bank_source_id AND c.created_by=NEW.created_by AND i.target_account_code=NEW.target_account_code AND d.status='draft' AND d.version=c.applied_draft_version AND EXISTS(SELECT 1 FROM json_each(c.plan_json,'$.parts') p WHERE json_extract(p.value,'$.item_id')=NEW.item_id AND json_extract(p.value,'$.amount_cents')=NEW.amount_cents AND json_extract(p.value,'$.counterparty_id')=i.counterparty_id))
 OR NEW.amount_cents+(SELECT COALESCE(sum(a.amount_cents),0) FROM migration_clearance_allocations a WHERE a.item_id=NEW.item_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=a.command_id))>(SELECT amount_cents FROM migration_open_items WHERE id=NEW.item_id)
 OR EXISTS(SELECT 1 FROM migration_clearance_commands c JOIN drafts d ON d.id=c.bank_draft_id WHERE c.id=NEW.command_id AND (d.description<>json_extract(c.plan_json,'$.description') OR (SELECT count(*) FROM draft_lines WHERE draft_id=d.id)<>json_array_length(c.plan_json,'$.lines') OR EXISTS(SELECT 1 FROM json_each(c.plan_json,'$.lines') expected LEFT JOIN draft_lines l ON l.draft_id=d.id AND l.ordinal=CAST(expected.key AS INTEGER) LEFT JOIN draft_line_auxiliaries ax ON ax.draft_id=l.draft_id AND ax.ordinal=l.ordinal WHERE l.account_code IS NOT json_extract(expected.value,'$.account_code') OR printf('%d.%02d',l.debit_cents/100,l.debit_cents%100)<>json_extract(expected.value,'$.debit') OR printf('%d.%02d',l.credit_cents/100,l.credit_cents%100)<>json_extract(expected.value,'$.credit') OR json(coalesce(ax.values_json,'{}'))<>json(json_extract(expected.value,'$.auxiliary_values')))))
 OR EXISTS(SELECT 1 FROM migration_clearance_commands c JOIN sources s ON s.id=c.bank_source_id JOIN migration_open_items i ON i.id=NEW.item_id WHERE c.id=NEW.command_id AND ((i.kind='payable')<>(s.direction='expense') OR i.counterparty_id<>json_extract(c.plan_json,'$.bank_party_id') OR NOT EXISTS(SELECT 1 FROM company_master_entities e WHERE e.id=i.counterparty_id AND e.active=1 AND (e.name=s.counterparty OR EXISTS(SELECT 1 FROM company_master_aliases ax WHERE ax.entity_id=e.id AND ax.original=s.counterparty AND ax.status='approved')))))
 OR EXISTS(SELECT 1 FROM migration_clearance_commands c,json_each(c.plan_json,'$.lines') expected WHERE c.id=NEW.command_id AND json_extract(expected.value,'$.account_code')<>c.bank_account_code AND (json_extract(expected.value,'$.account_code') NOT IN (SELECT json_extract(x.value,'$.clearing_account') FROM json_each(c.plan_json,'$.parts') x) OR CAST(replace(json_extract(expected.value,CASE json_extract(c.plan_json,'$.direction') WHEN 'expense' THEN '$.debit' ELSE '$.credit' END),'.','') AS INTEGER)<>(SELECT sum(json_extract(x.value,'$.amount_cents')) FROM json_each(c.plan_json,'$.parts') x WHERE json_extract(x.value,'$.clearing_account')=json_extract(expected.value,'$.account_code'))))
 THEN RAISE(ABORT,'Historical settlement exceeds verified remaining balance or command scope') END;
END;
CREATE TRIGGER migration_clearance_reversal_proof BEFORE INSERT ON migration_clearance_reversals BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM migration_clearance_commands c JOIN drafts d ON d.id=c.bank_draft_id JOIN periods p ON p.book_id=c.bank_book_id WHERE c.id=NEW.command_id AND c.project_id=NEW.project_id AND c.bank_book_id=NEW.bank_book_id AND c.created_by<>NEW.created_by AND d.status='draft' AND d.version=c.applied_draft_version AND p.status='open') THEN RAISE(ABORT,'Historical clearance reversal needs independent current unreviewed draft') END;
END;
CREATE TRIGGER migration_legacy_draft_lines_delete BEFORE DELETE ON draft_lines WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a JOIN migration_clearance_commands c ON c.id=a.command_id WHERE c.bank_draft_id=OLD.draft_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=c.id)) BEGIN SELECT RAISE(ABORT,'Confirmed historical clearance journal is immutable until independent reversal');END;
CREATE TRIGGER migration_legacy_draft_lines_update BEFORE UPDATE ON draft_lines WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a JOIN migration_clearance_commands c ON c.id=a.command_id WHERE c.bank_draft_id=OLD.draft_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=c.id)) BEGIN SELECT RAISE(ABORT,'Confirmed historical clearance journal is immutable until independent reversal');END;
CREATE TRIGGER migration_legacy_draft_lines_insert BEFORE INSERT ON draft_lines WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a JOIN migration_clearance_commands c ON c.id=a.command_id WHERE c.bank_draft_id=NEW.draft_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=c.id)) BEGIN SELECT RAISE(ABORT,'Confirmed historical clearance journal is immutable until independent reversal');END;
CREATE TRIGGER migration_legacy_draft_aux_delete BEFORE DELETE ON draft_line_auxiliaries WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a JOIN migration_clearance_commands c ON c.id=a.command_id WHERE c.bank_draft_id=OLD.draft_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=c.id)) BEGIN SELECT RAISE(ABORT,'Confirmed historical clearance auxiliaries are immutable');END;
CREATE TRIGGER migration_legacy_draft_aux_update BEFORE UPDATE ON draft_line_auxiliaries WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a JOIN migration_clearance_commands c ON c.id=a.command_id WHERE c.bank_draft_id=OLD.draft_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=c.id)) BEGIN SELECT RAISE(ABORT,'Confirmed historical clearance auxiliaries are immutable');END;
CREATE TRIGGER migration_legacy_draft_aux_insert BEFORE INSERT ON draft_line_auxiliaries WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a JOIN migration_clearance_commands c ON c.id=a.command_id WHERE c.bank_draft_id=NEW.draft_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=c.id)) BEGIN SELECT RAISE(ABORT,'Confirmed historical clearance auxiliaries are immutable');END;
CREATE TRIGGER migration_legacy_draft_identity BEFORE UPDATE ON drafts WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a JOIN migration_clearance_commands c ON c.id=a.command_id WHERE c.bank_draft_id=OLD.id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=c.id)) BEGIN
 SELECT CASE WHEN NEW.description<>OLD.description OR NEW.status=OLD.status OR NEW.version<>OLD.version+1 OR NOT ((OLD.status='draft' AND NEW.status='approved') OR (OLD.status='approved' AND NEW.status='exported')) OR (SELECT sum(a.amount_cents) FROM migration_clearance_allocations a JOIN migration_clearance_commands c ON c.id=a.command_id WHERE c.bank_draft_id=OLD.id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=c.id))<>(SELECT amount_cents FROM sources WHERE id=OLD.source_id) THEN RAISE(ABORT,'Historical clearance only permits explicit review then export of complete allocation') END;
END;
CREATE TRIGGER migration_legacy_source_isolation BEFORE INSERT ON bank_source_dispositions WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a WHERE a.bank_source_id=NEW.source_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=a.command_id)) BEGIN SELECT RAISE(ABORT,'Cannot hide bank source with active historical clearance');END;
CREATE TRIGGER migration_legacy_bank_link BEFORE INSERT ON ai_bank_links WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a WHERE a.bank_source_id=NEW.bank_source_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=a.command_id)) BEGIN SELECT RAISE(ABORT,'Historical clearance and current business matching are exclusive');END;
CREATE TRIGGER migration_legacy_current_settlement BEFORE INSERT ON settlement_allocations WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a WHERE a.bank_source_id=NEW.bank_source_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=a.command_id)) BEGIN SELECT RAISE(ABORT,'Historical and current settlement allocations are exclusive');END;
CREATE TRIGGER migration_legacy_fact_revision BEFORE INSERT ON fact_revisions WHEN EXISTS(SELECT 1 FROM migration_clearance_allocations a WHERE a.bank_source_id=NEW.old_source_id AND NOT EXISTS(SELECT 1 FROM migration_clearance_reversals r WHERE r.command_id=a.command_id)) BEGIN SELECT RAISE(ABORT,'Historical clearance must be reversed before source revision');END;
CREATE TRIGGER migration_open_items_immutable_update BEFORE UPDATE ON migration_open_items BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
CREATE TRIGGER migration_open_items_immutable_delete BEFORE DELETE ON migration_open_items BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
CREATE TRIGGER migration_clearance_previews_immutable_update BEFORE UPDATE ON migration_clearance_previews BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
CREATE TRIGGER migration_clearance_previews_immutable_delete BEFORE DELETE ON migration_clearance_previews BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
CREATE TRIGGER migration_clearance_commands_immutable_update BEFORE UPDATE ON migration_clearance_commands BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
CREATE TRIGGER migration_clearance_commands_immutable_delete BEFORE DELETE ON migration_clearance_commands BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
CREATE TRIGGER migration_clearance_allocations_immutable_update BEFORE UPDATE ON migration_clearance_allocations BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
CREATE TRIGGER migration_clearance_allocations_immutable_delete BEFORE DELETE ON migration_clearance_allocations BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
CREATE TRIGGER migration_clearance_reversals_immutable_update BEFORE UPDATE ON migration_clearance_reversals BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
CREATE TRIGGER migration_clearance_reversals_immutable_delete BEFORE DELETE ON migration_clearance_reversals BEGIN SELECT RAISE(ABORT,'Historical settlement evidence is immutable');END;
